const LIMIT = 100_000;
const res = Array(LIMIT + 1).fill(false);
res[0] = false;
res[1] = true;

for (let i = 2; i <= LIMIT; i++) {
    let canWin = false;

    for (let j = 1; j * j <= i; j++) {
        if (!res[i - j * j]) {
            canWin = true;
            break;
        }
    }

    res[i] = canWin;
}

/**
 * @param {number} n
 * @return {boolean}
 */
var winnerSquareGame = function(n) {
    return res[n];
};
